func IsFirstPartyProtectedProfileMethod(methodID string) bool {
	if _, ok := FirstPartyProfileMethod("desktop_machine_product_v1", methodID); ok {
		return true
	}
	if _, ok := FirstPartyProfileMethod("desktop_account_product_v1", methodID); ok {
		return true
	}
	_, ok := FirstPartyProfileMethod("bundled_avatar_v1", methodID)
	return ok
}
